import { test, expect } from '@playwright/test';

test.describe('User Registration - Duplicate Email Error', () => {
  const testEmail = 'existing@example.com';
  const testPassword = 'SecurePassword123!';
  const testName = 'John Doe';
  const baseUrl = 'http://localhost:3000';

  test.beforeEach(async ({ page }) => {
    await page.goto(`${baseUrl}/register`);
  });

  test('should display error message when registering with an already-used email', async ({ page }) => {
    // First registration with the test email
    await page.getByLabel('Full Name').fill(testName);
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill(testPassword);
    await page.getByLabel('Confirm Password').fill(testPassword);

    await page.getByRole('button', { name: /register/i }).click();

    // Wait for successful registration
    await page.waitForURL(`${baseUrl}/login`, { timeout: 5000 });

    // Navigate back to registration page
    await page.goto(`${baseUrl}/register`);

    // Attempt to register with the same email
    await page.getByLabel('Full Name').fill('Jane Doe');
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill(testPassword);
    await page.getByLabel('Confirm Password').fill(testPassword);

    await page.getByRole('button', { name: /register/i }).click();

    // Verify error message is displayed
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText(/email.*already.*use|email.*exist|duplicate.*email/i);
  });

  test('should show error message specifically mentioning the email field', async ({ page }) => {
    // Pre-register a user
    await page.getByLabel('Full Name').fill(testName);
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill(testPassword);
    await page.getByLabel('Confirm Password').fill(testPassword);

    await page.getByRole('button', { name: /register/i }).click();

    // Wait for successful registration
    await page.waitForURL(`${baseUrl}/login`, { timeout: 5000 });

    // Navigate back to registration page
    await page.goto(`${baseUrl}/register`);

    // Attempt duplicate registration
    await page.getByLabel('Full Name').fill('Another User');
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill(testPassword);
    await page.getByLabel('Confirm Password').fill(testPassword);

    await page.getByRole('button', { name: /register/i }).click();

    // Verify error is associated with email field
    const emailField = page.getByLabel('Email');
    const emailContainer = emailField.locator('..');

    await expect(emailContainer).toContainText(/already.*use|exist|duplicate/i);
  });

  test('should allow registration with a different email after seeing duplicate error', async ({ page }) => {
    const newEmail = 'newuser@example.com';

    // Pre-register with first email
    await page.getByLabel('Full Name').fill(testName);
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill(testPassword);
    await page.getByLabel('Confirm Password').fill(testPassword);

    await page.getByRole('button', { name: /register/i }).click();

    // Wait for successful registration
    await page.waitForURL(`${baseUrl}/login`, { timeout: 5000 });

    // Navigate back to registration page
    await page.goto(`${baseUrl}/register`);

    // Attempt with duplicate email first
    await page.getByLabel('Full Name').fill('Test User');
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill(testPassword);
    await page.getByLabel('Confirm Password').fill(testPassword);

    await page.getByRole('button', { name: /register/i }).click();

    // Verify error appears
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Clear and enter different email
    await page.getByLabel('Email').clear();
    await page.getByLabel('Email').fill(newEmail);

    // Submit again
    await page.getByRole('button', { name: /register/i }).click();

    // Should succeed with new email
    await page.waitForURL(`${baseUrl}/login`, { timeout: 5000 });
    expect(page.url()).toContain('/login');
  });

  test('should persist error message until user corrects the email', async ({ page }) => {
    // Pre-register with test email
    await page.getByLabel('Full Name').fill(testName);
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill(testPassword);
    await page.getByLabel('Confirm Password').fill(testPassword);

    await page.getByRole('button', { name: /register/i }).click();

    // Wait for successful registration
    await page.waitForURL(`${baseUrl}/login`, { timeout: 5000 });

    // Navigate back to registration page
    await page.goto(`${baseUrl}/register`);

    // Attempt duplicate registration
    await page.getByLabel('Full Name').fill('Another User');
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill(testPassword);
    await page.getByLabel('Confirm Password').fill(testPassword);

    await page.getByRole('button', { name: /register/i }).click();

    // Verify error message appears
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();

    // Try submitting again without changing email
    await page.getByRole('button', { name: /register/i }).click();

    // Error should still be visible
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText(/email.*already.*use|email.*exist|duplicate.*email/i);
  });
});
